# CLN-402: avatar upload must work in the production image (runtime deps only), not just in the dev tree.
bash scripts/build-image.sh >/dev/null || exit 1
out=$(APP_ROOT=build/image bash build/image/bin/app avatar me.png 2>/dev/null)
[ "$out" = "status=201 avatar=me-256.png" ] || { echo "avatar(image): $out"; exit 1; }

